-- agent-ci: generated by `npm run guide:content` from content/guide/agent-ci.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 13,
  "outcome": "Вы запускаете агента в CI — ответы на `@claude`, автоматическое ревью, безголовые прогоны `claude -p` — с секретами и правами под контролем.",
  "blocks": [
    {
      "type": "text",
      "text": "Агент не обязан жить только в вашем терминале. В CI он отвечает на упоминания в задачах и PR, ревьюит каждый PR и выполняет рутину по расписанию — тот же Claude Code, только без интерактива."
    },
    {
      "type": "heading",
      "text": "GitHub Actions за одну команду"
    },
    {
      "type": "command",
      "code": "/install-github-app",
      "caption": "Запустите в Claude Code: команда установит приложение GitHub, добавит секрет и подготовит файл workflow."
    },
    {
      "type": "code",
      "file": ".github/workflows/claude.yml",
      "code": "name: Claude Code\non:\n  issue_comment:\n    types: [created]\njobs:\n  claude:\n    if: contains(github.event.comment.body, '@claude')\n    runs-on: ubuntu-latest\n    permissions:\n      contents: write\n      pull-requests: write\n      issues: write\n      id-token: write\n    steps:\n      - uses: actions/checkout@v6\n      - uses: anthropics/claude-code-action@v1\n        with:\n          anthropic_api_key: ${{ secrets.ANTHROPIC_API_KEY }}",
      "caption": "Теперь комментарий «@claude поправь опечатку в README» в задаче или PR запустит агента. Ключ хранится в секретах репозитория, а не в файле."
    },
    {
      "type": "heading",
      "text": "Два режима"
    },
    {
      "type": "list",
      "items": [
        "**По упоминанию**: агент отвечает на `@claude` в комментариях — так работает workflow без входа `prompt`.",
        "**Автоматический**: с входом `prompt` агент выполняет заданную работу на событие или по расписанию — например, ревью каждого PR."
      ]
    },
    {
      "type": "heading",
      "text": "Безголовый запуск"
    },
    {
      "type": "text",
      "text": "В любом CI, не только в GitHub, работает `claude -p`: запрос без интерактива, результат — в stdout. Для GitLab в документации есть готовый пример."
    },
    {
      "type": "command",
      "code": "claude -p \"Найди в изменениях ветки места без тестов\" --output-format json --allowedTools \"Read,Grep,Glob\" --max-turns 10",
      "caption": "`--allowedTools` разрешает только чтение, `--max-turns` ограничивает число ходов, а JSON удобно разбирать скриптом."
    },
    {
      "type": "session",
      "title": "ci · feature/promo",
      "summary": "Симуляция прогона в CI: claude -p читает изменения ветки, находит место без тестов и возвращает результат в JSON для следующего шага пайплайна.",
      "lines": [
        {
          "kind": "command",
          "text": "claude -p \"Найди места без тестов\" --output-format json",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Читаю изменения ветки feature/promo: 6 файлов"
        },
        {
          "kind": "info",
          "text": "Без тестов: src/cart/promo.ts — ветка с просроченным кодом"
        },
        {
          "kind": "done",
          "text": "{\"result\": \"Без тестов: 1 место\", \"session_id\": \"…\"}"
        }
      ]
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "В CI агент работает без вас",
